import{_ as p,a0 as d,w as a,s as l,ao as e,I as r,x as n,a1 as t,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux有问必答：如何在Linux命令行中刻录ISO或NRG镜像到DVD | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何在Linux命令行中刻录ISO或NRG镜像到DVD | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何在Linux命令行中刻录ISO或NRG镜像到DVD | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何在Linux命令行中刻录ISO或NRG镜像到DVD | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20141014 Linux FAQs with Answers--How to burn an ISO or NRG image to a DVD from the command line on Linux","title":"Linux有问必答：如何在Linux命令行中刻录ISO或NRG镜像到DVD","tag":"201410","desc":""},"relativePath":"201410/20141014 Linux FAQs with Answers--How to burn an ISO or NRG image to a DVD from the command line on Linux.md","filePath":"[post].md"}'),m={name:"201410/20141014 Linux FAQs with Answers--How to burn an ISO or NRG image to a DVD from the command line on Linux.md"};function u(g,o,D,f,x,_){const i=d("Link");return a(),l("div",null,[o[19]||(o[19]=e(`<h1 id="linux有问必答-如何在linux命令行中刻录iso或nrg镜像到dvd" tabindex="-1">Linux有问必答：如何在Linux命令行中刻录ISO或NRG镜像到DVD <a class="header-anchor" href="#linux有问必答-如何在linux命令行中刻录iso或nrg镜像到dvd" aria-label="Permalink to “Linux有问必答：如何在Linux命令行中刻录ISO或NRG镜像到DVD”">​</a></h1><blockquote><p><strong>问题</strong>：我需要在Linux机器上使用DVD刻录机刻录一个镜像文件（.iso或.nrg）到DVD，有没有一个既快捷又简易的方法，最好是使用命令行工具？</p></blockquote><p>最常见的两种镜像文件格式是ISO（.iso为文件扩展名）和NRG（.nrg为文件扩展名）。ISO格式是一个由ISO（国际标准组织）创立的全球标准，因此被大多数操作系统所支持，它提供了很高的便携性。另一方面，NRG格式是由Nero AG开发的私有格式，Nero AG是一个很流行的磁盘镜像和刻录软件公司。</p><p>下面来解答怎样从Linux命令行刻录.iso或.nrg镜像到DVD。</p><h3 id="刻录-iso镜像文件到dvd" tabindex="-1">刻录.ISO镜像文件到DVD <a class="header-anchor" href="#刻录-iso镜像文件到dvd" aria-label="Permalink to “刻录.ISO镜像文件到DVD”">​</a></h3><p>要刻录.iso镜像文件到DVD，我们将使用<strong>growisofs</strong>这个工具：</p><pre><code> # growisofs -dvd-compat -speed=4 -Z /dev/dvd1=WindowsXPProfessionalSP3Original.iso 
</code></pre><p>在上面的命令行中，“-dvd-compat”选项提供了与DVD-ROM/-Video的最大介质兼容性。在一次写入式 DVD+R 或 DVD-R 上下文中，导致不可添加记录（关闭磁盘）。</p><p>“-Z /dev/dvd1=filename.iso”选项表示我们刻录.iso文件到设备选单（/dev/dvd1）中选择的介质中。</p><p>“-speed=N”参数指定了DVD刻录机的刻录速度，这与驱动自身的能力直接相关。“-speed=8”将以8x刻录，“-speed=16”将以16x刻录，以此类推。没有该参数，growisofs将默认以最低速刻录，在这里是4x。你可以根据你刻录机的可用速度和磁盘类型选择合适的刻录速度。</p>`,10)),r("p",null,[o[1]||(o[1]=n("你可以根据",-1)),t(i,{href:"http://linux.cn/article-4081-1.html"},{default:s(()=>[...o[0]||(o[0]=[n("此教程",-1)])]),_:1}),o[2]||(o[2]=n("找出你的DVD刻录机的设备名称和它所支持的写入速度。",-1))]),o[20]||(o[20]=e(`<p><img src="https://farm3.staticflickr.com/2947/15510172352_5c09c2f495_z.jpg" alt=""></p><p>刻录进程完成后，磁盘会自动弹出。</p><h3 id="把nrg镜像转换为iso格式" tabindex="-1">把NRG镜像转换为ISO格式 <a class="header-anchor" href="#把nrg镜像转换为iso格式" aria-label="Permalink to “把NRG镜像转换为ISO格式”">​</a></h3><p>由于ISO被广为采用，刻录.iso镜像到CD/DVD就非常简单。但是，要刻录一个.nrg镜像则首先需要将它转换为.iso格式。</p><p>把一个.nrg镜像文件转换到.iso格式，你可以使用nrg2iso这个工具。它是一个开源程序，用来将Nero Burning Rom创建的镜像转换到标准的.iso（ISO9660）文件。</p><p>在Debian及其衍生版上安装<strong>nrg2iso</strong>：</p><pre><code># aptitude install nrg2iso
</code></pre><p>在基于Red Hat的发行版上安装<strong>nrg2iso</strong>：</p><pre><code># yum install nrg2iso 
</code></pre>`,9)),r("p",null,[o[4]||(o[4]=n("在CentOS/RHEL上，你需要先启用",-1)),t(i,{href:"http://xmodulo.com/how-to-set-up-rpmforge-repoforge-repository-on-centos.html"},{default:s(()=>[...o[3]||(o[3]=[n("Repoforge仓库",-1)])]),_:1}),o[5]||(o[5]=n("，再通过",-1)),o[6]||(o[6]=r("strong",null,"yum",-1)),o[7]||(o[7]=n("安装。",-1))]),o[21]||(o[21]=e(`<p>安装完nrg2iso包后，使用以下命令来将.nrg镜像转换到.iso格式：</p><pre><code># nrg2iso filename.nrg filename.iso 
</code></pre><p><img src="https://farm3.staticflickr.com/2945/15507409981_99eddd2577_z.jpg" alt=""></p><p>转换完成后，在当前目录中会出现一个.iso文件：</p><p><img src="https://farm4.staticflickr.com/3945/15323823510_c933d7710f_z.jpg" alt=""></p><p>###检查已刻录介质的完整性###</p><p>关于这一点，你可以通过将刻录的DVD的校验和与原始.iso文件的md5校验和进行对比，以检查所刻录介质的完整性。如果两者相同，你就可以放心了，因为刻录成功了。</p><p>然而，当你使用nrg2iso来将.nrg镜像转换为.iso格式后，你需要明白一点，nrg2iso创建的.iso文件的大小不是2048的倍数（通常，.iso文件的大小是它的倍数）。因此，常规的校验和对比，该.iso文件和刻录介质的内容不一样。</p><p>另一方面，如果你已经刻录了一个不是由.nrg文件转换而来的.iso镜像，你可以使用以下命令来检查记录到DVD中的数据的完整性。替换“/dev/dvd1”为你的设备名。</p><pre><code># md5sum filename.iso; dd if=/dev/dvd1 bs=2048 count=$(($(stat -c &quot;%s&quot; filename.iso) / 2048)) | md5sum 
</code></pre><p>命令的第一部分计算.iso文件的md5校验和，而第二部分则读取/dev/dvd1中的磁盘内容，然后通过管道输出给md5sum工具。“bs=2048”表示dd命令将使用2048字节块为单位检查，因为原始iso文件以2048为单位划分。</p><p><img src="https://farm3.staticflickr.com/2949/15487396726_bcf47d536f_z.jpg" alt=""></p><p>如果两个md5校验和的值相同，这就意味着刻录的介质是有效的。</p><hr>`,14)),r("p",null,[o[9]||(o[9]=n("via: ",-1)),t(i,{href:"http://ask.xmodulo.com/burn-iso-nrg-image-dvd-command-line.html"},{default:s(()=>[...o[8]||(o[8]=[n("http://ask.xmodulo.com/burn-iso-nrg-image-dvd-command-line.html",-1)])]),_:1})]),r("p",null,[o[12]||(o[12]=n("译者：",-1)),t(i,{href:"https://github.com/GOLinux"},{default:s(()=>[...o[10]||(o[10]=[n("GOLinux",-1)])]),_:1}),o[13]||(o[13]=n(" 校对：",-1)),t(i,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...o[11]||(o[11]=[n("Caroline",-1)])]),_:1})]),r("p",null,[o[16]||(o[16]=n("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...o[14]||(o[14]=[n("LCTT",-1)])]),_:1}),o[17]||(o[17]=n(" 原创翻译，",-1)),t(i,{href:"http://linux.cn/"},{default:s(()=>[...o[15]||(o[15]=[n("Linux中国",-1)])]),_:1}),o[18]||(o[18]=n(" 荣誉推出",-1))])])}const S=p(m,[["render",u]]);export{T as __pageData,S as default};
